def hull_of(points):
    # convex hull (Shoelace) and point-in-hull test
    import itertools
    P=sorted(points)
    def area(O,A,B): return (A[0]-O[0])*(B[1]-O[1])-(A[1]-O[1])*(B[0]-O[0])
    if len(P)<=2: return set(P)
    hull=[P[0]]
    for p in P[1:]:
        while len(hull)>=2 and area(hull[-2],hull[-1],p)<0: hull.pop()
        hull.append(p)
    while True:
        q=P[-(len(P)-len(hull))+1]
        if area(hull[-2],hull[-1],q)<=0: break
        hull.append(q)
    return hull
