def pinhull(P,x):
    # P=(N,2) float, x=(2,)
    # solve P.T @ alpha = x, alpha >=0, sum=1
    A=np.vstack([P.T,np.ones(len(P))])
    b=np.array(x+[1.0])
    try: alpha=np.linalg.lstsq(A,b,rcond=None)[0]
