import numpy as np
for n in range(1,6):
    di=G[f'Demo pair {n} input']; do=G[f'Demo pair {n} output']
    Bs=comps(di,2)
    kept={p for p in Bs if all(do[p[0]+dy][p[1]+dx]==2 for dy in (0,1) for dx in (0,1))}
    dropped=[p for p in Bs if p not in kept]
    def cheb(p,q): return max(abs(p[0]-q[0]),abs(p[1]-q[1]))
    print('pair',n,'kept' if len(Bs)<1 else '')
    for p in sorted(Bs,key=lambda b:(b[0],b[1])):
        others=[q for q in Bs if q!=p]
        best=min(others,key=lambda q:cheb(p,q)) if others else None
        tag='K' if p in kept else 'D'
        print(tag,p,'best:',(best is not None,best),'cheb' if best else '-','cells:',sorted(cb(p)))
